import{z as o,x as d,o as t,c as p,q as i,j as r,D as e,d as E,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"嵌套虚拟化","description":"","frontmatter":{"title":"嵌套虚拟化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nested-virtualization.md","filePath":"cs/nested-virtualization.md","lastUpdated":1791413859000}'),A={name:"cs/nested-virtualization.md"};function L(c,a,B,h,_,m){const s=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="嵌套虚拟化" tabindex="-1">嵌套虚拟化 <a class="header-anchor" href="#嵌套虚拟化" aria-label="Permalink to &quot;嵌套虚拟化&quot;">​</a></h1><div class="epigraph"><p>嵌套让 L1 客户自己当 hypervisor 跑 L2：L0 必须模拟或转发 VMX 操作，exit 可能翻倍。</p><footer>—— 据 Linux KVM nested 文档；Intel 对 nested VMX 的说明；[VM-exit](/cs/vmx-vmexit) 为代价先修</footer></div><p><a href="/cs/live-migration">热迁移</a> 已够复杂。云上还要在 VM 里再开 KVM。缺口是 <strong>nested</strong>：谁处理 L2 的 exit。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>L2 执行导致 L1 想 VM-exit 到 L1 内核，实际先到 L0。L0 或转发或模拟 VMCS。缺口：性能；安全（L1 逃到 L0）；与 <a href="/cs/shadow-page-table">EPT</a> 多一层。本课不把所有硬件 nested 能力位列出。</p><p><span class="marginnote">直觉类比：嵌套像转租——L1 本是租客，现在想当二房东把房子隔间转租给 L2。可房产证只在房东 L0 手里：L2 每次「想找房东」（VM-exit），请求都先落到 L0，由 L0 决定自己处理还是转给二房东 L1。</span></p><p><span class="marginnote">用于测试 hypervisor、嵌套云。对象是两层 VMX，不是容器套容器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>L0 KVM nested 模块维护两层 VMCS 影子。对照 <a href="/cs/sched-domains">调度域</a>：都是分层，一个 CPU 拓扑一个特权。对照 <a href="/cs/fuse">FUSE</a>：无关。对照 Firecracker 后课：通常禁止 nested 减攻击面。</p>',9)),(t(),r(l,null,{default:e(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20L2%5B%22L2%20%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20EX%5B%22%E6%9C%AC%E6%84%8F%E9%80%80%E5%88%B0%20L1%22%5D%0A%20%20EX%20--%3E%20L0%5B%22%E5%AE%9E%E9%99%85%E5%85%88%20L0%22%5D%0A%20%20L0%20--%3E%20L1%5B%22%E5%86%8D%E6%B3%A8%E5%85%A5%20L1%20VMM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>嵌套把虚拟化递归化，使「在 VM 里开发 hypervisor」成为可能，税是 exit 与复杂性。生产常关。不要写成套娃梗。与 <a href="/cs/kabi-module-signing">kABI</a>：L1 内核模块仍要匹配 L1。</p><p><span class="marginnote">数字实例：单层虚拟化一次 VM-exit 通常在数千至上万个处理器周期量级；嵌套下 L2 的一次退出往往拆成两段——先陷入 L0，L0 模拟/转发后把事件注入 L1——再叠加两层 EPT 的缺页路径，同一事件的代价轻松翻倍以上。</span></p><p><span class="marginnote">常见误区：初学者把嵌套虚拟化当成「容器套容器」。容器共用宿主一个内核，根本不碰 VMX；嵌套是两套完整的虚拟化栈，L0 还要替 L1 维护影子 VMCS。复杂度、开销与攻击面都不是一个量级——这正是生产环境默认关闭 nested 的原因。</span></p><p>bug 类常是双重影子不同步。</p><p>实现上：L2 的 EPT 由 L1 管理，L0 再嵌一层，缺页路径变长。生产关 nested 是减攻击面。测试 hypervisor 是主要正当理由。 读法上只引用<a href="/cs/live-migration">上一课</a>的结论，不把对象换成训练推理或限价簿。</p>',6)),(t(),r(l,null,{default:e(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22L2%20%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20E1%5B%22L1%20%E7%9A%84%20EPT%EF%BC%9AL2%20%E7%89%A9%E7%90%86%20%E2%86%92%20L1%20%E7%89%A9%E7%90%86%22%5D%0A%20%20E1%20--%3E%20E0%5B%22L0%20%E7%9A%84%20EPT%EF%BC%9AL1%20%E7%89%A9%E7%90%86%20%E2%86%92%20%E7%9C%9F%E5%AE%9E%E7%89%A9%E7%90%86%22%5D%0A%20%20E0%20--%3E%20RAM%5B%22%E7%9C%9F%E5%AE%9E%E5%86%85%E5%AD%98%22%5D%0A%20%20MISS%5B%22%E4%BB%BB%E4%B8%80%E5%B1%82%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20OWN%5B%22%E7%94%B1%E8%AF%A5%E5%B1%82%E6%89%80%E5%B1%9E%E7%9A%84%20VMM%20%E5%A4%84%E7%90%86%22%5D%0A%20%20OWN%20--%3E%20COST%5B%22%E5%9C%B0%E5%9D%80%E7%BF%BB%E8%AF%91%E8%B7%AF%E5%BE%84%E6%8B%89%E9%95%BF%EF%BC%8Cexit%20%E5%BC%80%E9%94%80%E5%8F%A0%E5%8A%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>嵌套虚拟化</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 AMD 与 Intel 的全部差异。不保证迁移嵌套 VM。Hypervisor 课序收口；下一课序容器运行时。</p><p>版本字段会变，课序钉的是机制对象「嵌套虚拟化」，不是某一主线内核的结构体名。 后课默认：可嵌套但贵且扩大攻击面。runc/containerd 如何用命名空间，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>嵌套：L0 转发/模拟 L1 的 VMX。</li><li>exit 与攻击面增加；生产常关。</li><li>容器运行时是下一课序。</li><li>出处：KVM nested；Intel nested VMX。</li></ul>',7))])}const M=o(A,[["render",L]]);export{V as __pageData,M as default};
